 const editor=$('[data-fs-editor]');editor.value=formula;$('[data-fs-font]').value=font;$('[data-fs-size]').value=String(size);$('[data-fs-ink]').value=ink;$('[data-fs-numbering]').value=numbering?'right':'none';$('[data-fs-number]').value=String(equationNumber);$('[data-fs-number-field]').hidden=!numbering;$('[data-fs-requirements]').value=requirements;
