 function symbolRows(){return formulaSymbolGroups.filter(group=>libraryGroup==='all'||group.id===libraryGroup).flatMap(group=>group.tokens.map(([label,token],index)=>({key:group.id+':'+index,group:group.label,groupId:group.id,index,label,token}))).filter(item=>{const terms=query.normalize('NFKC').toLocaleLowerCase().trim().split(/\s+/).filter(Boolean),text=[item.label,item.token,item.group].join(' ').normalize('NFKC').toLocaleLowerCase();return terms.every(term=>text.includes(term));});}
